import React, { useState, useEffect, useRef } from 'react';
import { useNavigate, Link, useLocation } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import { loginStart, loginSuccess, loginFailure, clearError } from '../../store/authSlice';
import { syncUserActivity } from '../../store/activitySlice';
import { enrollStudentAsync } from '../../store/contentSlice';
import { startCourse } from '../../store/activitySlice';
import { supabaseService } from '../../services/supabaseService';
import Button from '../../components/ui/Button';
import Input from '../../components/ui/Input';
import { Turnstile } from '@marsidev/react-turnstile';
import Icon from '../../components/AppIcon';
import { useToast } from '../../contexts/ToastContext';
import { useRateLimit } from '../../hooks/useRateLimit';

const Login = () => {
  const { addToast } = useToast();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [captchaToken, setCaptchaToken] = useState(null);
  const [localError, setLocalError] = useState('');
  const [localSuccess, setLocalSuccess] = useState('');
  const [requiresMfa, setRequiresMfa] = useState(false);
  const [mfaFactorId, setMfaFactorId] = useState(null);
  const [mfaCode, setMfaCode] = useState('');
  const navigate = useNavigate();
  const location = useLocation();
  const dispatch = useDispatch();
  const { isLoading, error, isAuthenticated, role } = useSelector((s) => s.auth);
  const turnstileRef = useRef(null);
  
  // Rate limit: Max 5 login attempts per minute per browser session
  const { checkRateLimit } = useRateLimit(5, 60000);

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    if (params.get('error') === 'suspended') {
      setLocalError('Your account has been suspended by an administrator.');
    }
    if (params.get('error') === 'deleted') {
      setLocalError('Your account has been permanently deleted.');
    }
    if (params.get('verified') === 'true') {
      setLocalSuccess('Email verified successfully! You can now sign in.');
    }
  }, []);

  useEffect(() => {
    if (isAuthenticated) {
      const params = new URLSearchParams(window.location.search);
      const redirectParam = params.get('redirect');
      const from = redirectParam || location.state?.from || '/';

      // Consume pending intake from guest enrollment flow
      const pendingIntake = JSON.parse(sessionStorage.getItem('pendingIntake') || 'null');
      if (pendingIntake) {
        const consumeIntake = async () => {
          try {
            const { data: { user } } = await supabaseService.supabase.auth.getUser();
            if (user) {
              if (pendingIntake.isTrack && pendingIntake.trackCourses?.length > 0) {
                await supabaseService.enrollInTrack(
                  user.id,
                  String(pendingIntake.courseId),
                  pendingIntake.trackCourses.map(String),
                  0
                );
                pendingIntake.trackCourses.forEach(cId => {
                  dispatch(enrollStudentAsync({ courseId: cId, type: 'academy' }));
                  dispatch(startCourse({ courseId: cId }));
                });
              } else if (pendingIntake.courseId) {
                dispatch(enrollStudentAsync({ courseId: pendingIntake.courseId, type: 'academy' }));
                dispatch(startCourse({ courseId: pendingIntake.courseId }));
              }
            }
          } catch (enrollErr) {
            console.warn('Auto-enrollment after login failed:', enrollErr);
          }
          sessionStorage.removeItem('pendingIntake');
        };
        consumeIntake();
      }

      if ((role === 'admin' || role === 'moderator' || role === 'stealth') && from === '/') navigate('/admin-dashboard');
      else navigate(from);
    }
  }, [isAuthenticated, navigate, role, location.state, dispatch]);

  useEffect(() => {
    if (error) {
      const t = setTimeout(() => dispatch(clearError()), 4000);
      return () => clearTimeout(t);
    }
  }, [error, dispatch]);

  const validateForm = () => {
    if (!requiresMfa) {
        if (!email || !password) {
          setLocalError('Please fill in all fields');
          return false;
        }
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRegex.test(email)) {
          setLocalError('Please enter a valid email address');
          return false;
        }
    } else {
        if (mfaCode.length < 6) {
            setLocalError('Please enter the full 6-digit code');
            return false;
        }
    }
    return true;
  };

  const [showBackupInput, setShowBackupInput] = useState(false);
  const [backupCode, setBackupCode] = useState('');

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLocalError('');
    
    // 1. Enforce Client-Side Rate Limit before doing anything
    if (!checkRateLimit('Login attempt')) {
        return;
    }

    if (!validateForm()) return;

    if (!requiresMfa && !captchaToken) {
        setLocalError('Please complete the security check');
        return;
    }

    dispatch(loginStart());

    try {
      if (requiresMfa) {
        if (showBackupInput) {
            // Backup code flow
            if (backupCode.length < 8) {
                setLocalError('Please enter a valid 8-character backup code.');
                dispatch(loginFailure(''));
                return;
            }
            await supabaseService.verifyAndResetMfaWithBackupCode(mfaFactorId ? null : (await supabaseService.supabase.auth.getUser()).data.user.id, backupCode);
            addToast('MFA has been reset using your backup code. Please sign in again.', 'success');
            setRequiresMfa(false);
            setShowBackupInput(false);
            setBackupCode('');
            dispatch(loginFailure('')); // Just reset loading
        } else {
            // Standard MFA flow
            const res = await supabaseService.completeMfaLogin(mfaFactorId, mfaCode);
            dispatch(loginSuccess({
                token: res.session.access_token,
                user: res.user,
                role: res.role
            }));
            dispatch(syncUserActivity(res.user.id));
        }
      } else {
        const res = await supabaseService.login(email, password, captchaToken);
        
        if (res.requiresMfa) {
            setRequiresMfa(true);
            setMfaFactorId(res.factorId);
            dispatch(clearError()); 
            dispatch(loginFailure('')); 
            return;
        }

        dispatch(loginSuccess({
            token: res.session.access_token,
            user: res.user,
            role: res.role
        }));
        dispatch(syncUserActivity(res.user.id));
      }
    } catch (err) {
      dispatch(loginFailure(err.message || 'Login failed'));
      // Reset captcha on failure to prevent "timeout-or-duplicate" errors
      if (turnstileRef.current) {
          turnstileRef.current.reset();
          setCaptchaToken(null);
      }
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-primary via-secondary to-accent flex items-center justify-center p-4">
      <div className="w-full max-w-md">
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow-2xl p-8">
          <h2 className="text-2xl font-bold mb-2">Sign in to LUC Hub</h2>
          <p className="text-sm text-gray-500 mb-6">Access opportunities and manage your profile</p>

          <div className="mb-4">
            <Button asChild variant="ghost" size="sm" className="px-2 py-1">
              <Link to="/">← Back to Home</Link>
            </Button>
          </div>

          {(localError || error) && (
            <div className="mb-4 text-sm text-red-700 bg-red-50 p-3 rounded-xl border border-red-100">{localError || error}</div>
          )}

          {localSuccess && (
            <div className="mb-4 text-sm text-green-700 bg-green-50 p-3 rounded-xl border border-green-100">{localSuccess}</div>
          )}

          <form onSubmit={handleSubmit} className="space-y-4">
            {!requiresMfa ? (
              <>
                <div>
                  <label className="block text-sm font-semibold mb-2">Email</label>
                  <Input value={email} onChange={(e) => setEmail(e.target.value)} type="email" />
                </div>
                <div>
                    <div className="flex items-center justify-between">
                    <label className="block text-sm font-semibold mb-2">Password</label>
                    <Link to="/forgot-password" size="xs" className="text-xs text-primary hover:underline mb-2">Forgot password?</Link>
                    </div>
                    <Input value={password} onChange={(e) => setPassword(e.target.value)} type="password" />
                </div>
                
                <div className="flex justify-center my-4 overflow-hidden rounded-xl border border-gray-100 dark:border-gray-700 p-2 bg-gray-50 dark:bg-gray-900/50">
                  <Turnstile 
                    ref={turnstileRef}
                    siteKey={import.meta.env.VITE_TURNSTILE_SITE_KEY} 
                    onSuccess={(token) => setCaptchaToken(token)}
                    onError={() => setLocalError('Security check failed. Please refresh.')}
                    theme="auto"
                  />
                </div>
              </>
            ) : (
                <div className="animate-in fade-in zoom-in duration-300 space-y-4 p-4 border border-emerald-500/20 bg-emerald-500/5 rounded-xl">
                    <div className="text-center">
                        <div className="mx-auto w-12 h-12 bg-emerald-500/20 text-emerald-600 rounded-full flex items-center justify-center mb-3">
                            <Icon name={showBackupInput ? "Shield" : "Smartphone"} size={24} />
                        </div>
                        <h3 className="font-bold text-primary">{showBackupInput ? "Recovery Protocol" : "Two-Factor Authentication"}</h3>
                        <p className="text-xs text-muted-foreground mt-1 mb-4">
                            {showBackupInput ? "Enter one of your 8-character backup codes." : "Enter the 6-digit code from your authenticator app."}
                        </p>
                    </div>
                    <div>
                        <Input 
                            value={showBackupInput ? backupCode : mfaCode} 
                            onChange={(e) => {
                                const val = e.target.value;
                                if (showBackupInput) setBackupCode(val.toUpperCase());
                                else setMfaCode(val.replace(/\D/g, ''));
                            }} 
                            type="text" 
                            maxLength={showBackupInput ? 8 : 6}
                            placeholder={showBackupInput ? "ABCDEFGH" : "000000"}
                            className="text-center tracking-[0.5em] font-mono text-lg"
                        />
                        <div className="mt-4 text-center space-y-2">
                            <button 
                                type="button"
                                onClick={() => {
                                    setShowBackupInput(!showBackupInput);
                                    setLocalError('');
                                }}
                                className="text-[10px] font-black uppercase tracking-widest text-muted-foreground hover:text-primary transition-colors flex items-center justify-center gap-1 mx-auto"
                            >
                                <Icon name={showBackupInput ? "Smartphone" : "Shield"} size={10} />
                                {showBackupInput ? "Use Authenticator App" : "Use Backup Code"}
                            </button>
                            <Link 
                                to="/contact?subject=Lost MFA Access#contact-form" 
                                className="text-[10px] font-black uppercase tracking-widest text-muted-foreground hover:text-primary transition-colors flex items-center justify-center gap-1"
                            >
                                <Icon name="HelpCircle" size={10} />
                                Having trouble? Contact Support
                            </Link>
                        </div>
                    </div>
                </div>
            )}

            <Button type="submit" disabled={isLoading} className="w-full mt-2">
                {isLoading ? 'Verifying...' : (requiresMfa ? 'Verify Code' : 'Sign in')}
            </Button>
            
            {requiresMfa && (
                <Button variant="ghost" size="sm" className="w-full mt-2" onClick={() => setRequiresMfa(false)}>
                    Cancel
                </Button>
            )}
          </form>

          {!requiresMfa && (
            <div className="mt-6 text-sm text-center">
                <p>Don't have an account? <Link className="text-primary font-semibold hover:underline" to={`/signup${location.search}`}>Create one</Link></p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Login;
