import { useState, useCallback } from 'react';
import { useToast } from '../contexts/ToastContext';

/**
 * useRateLimit - A client-side rate limiter for critical UI actions
 * Prevents users from spamming buttons or API calls.
 * Note: True rate limiting must also be enforced at the API/Cloudflare level.
 * 
 * @param {number} limit - Maximum number of allowed actions
 * @param {number} timeWindowMs - Time window in milliseconds (e.g., 60000 for 1 minute)
 */
export const useRateLimit = (limit = 3, timeWindowMs = 60000) => {
    const [attempts, setAttempts] = useState([]);
    const { addToast } = useToast();

    const checkRateLimit = useCallback((actionName = 'This action') => {
        const now = Date.now();
        
        // Filter out old attempts outside the time window
        const recentAttempts = attempts.filter(time => now - time < timeWindowMs);
        
        if (recentAttempts.length >= limit) {
            const oldestAttempt = recentAttempts[0];
            const timeUntilReset = Math.ceil((timeWindowMs - (now - oldestAttempt)) / 1000);
            
            addToast(`Rate limit exceeded. Please wait ${timeUntilReset} seconds before trying again.`, 'error');
            
            // Update state to clear old ones
            setAttempts(recentAttempts);
            return false; // Block action
        }
        
        // Action allowed, record the attempt
        setAttempts([...recentAttempts, now]);
        return true; // Allow action
    }, [attempts, limit, timeWindowMs, addToast]);

    const resetRateLimit = useCallback(() => {
        setAttempts([]);
    }, []);

    return { checkRateLimit, resetRateLimit };
};

export default useRateLimit;
